Definition pc_set_hlim (c : pcore) (hl : Z) : pcore :=
  mkPC (pc_blim_has c) (pc_blim c) (pc_len c) (pc_len0 c) (pc_skip c) hl (pc_state c) (pc_f c).
Definition pst_set_c (d : pst) (c : pcore) : pst :=
  mkPST c (ps_S d) (ps_L d) (ps_ns d) (ps_ls d) (ps_em d) (ps_h d) (ps_u d) (ps_es d) (ps_insz d) (ps_g d) (ps_rdi d) (ps_LBn d) (ps_st d) (ps_errv d).
Definition pst_set_cg (d : pst) (c : pcore) (g : bool) : pst :=
  mkPST c (ps_S d) (ps_L d) (ps_ns d) (ps_ls d) (ps_em d) (ps_h d) (ps_u d) (ps_es d) (ps_insz d) g (ps_rdi d) (ps_LBn d) (ps_st d) (ps_errv d).

Lemma PutL_set_hlim : forall sp P p0 bs LB0 L0 es0 h0 d hl g,
  PutL sp P p0 bs LB0 L0 es0 h0 d -> 0 <= hl <= pc_hlim (ps_c d) -> PutL sp P p0 bs LB0 L0 es0 h0 (pst_set_cg d (pc_set_hlim (ps_c d) hl) g).
Proof.
  intros sp P p0 bs LB0 L0 es0 h0 d hl g L HL.
  destruct L as (PCOK & OWN & MOWN & HOWN & EH & ESH & NEW & NEWB & WINL & WINB & DFB & HST & U01 & CAP & LES & INZ & LEN1 & HDJ & HNEW & HL8 & SK62 & AOWN & LS & ESS).
  unfold PutL, pst_set_cg, pc_set_hlim. cbn [ps_c ps_S ps_L ps_ns ps_ls ps_em ps_h ps_u ps_es ps_insz ps_g ps_rdi ps_LBn ps_st ps_errv pc_state pc_len pc_hlim].
